  display: block;
  height: 100%;
}
:host .header-panel {
  background-color: var(--headerBackground);
  color: var(--headerColor);
  position: absolute;
  top: 0px;
  left: 0px;
  height: 36px;
  width: 100%;
  text-align: center;
  line-height: 36px;
  border-bottom: 1px solid var(--headerBorder);
}
:host .header-panel mat-icon {
  display: inline-block;
  vertical-align: text-top;
}
:host .work-panel {
  position: absolute;
  top: 37px;
  left: 0px;
  right: 0px;
  bottom: 0px;
  background-color: var(--mat-table-background-color);
  overflow: hidden;
}
:host .container {
  display: flex;
  flex-direction: column;
  min-width: 300px;
  position: absolute;
  bottom: 0px;
  top: 0px;
  left: 0px;
  right: 0px;
  overflow-y: auto;
}
:host .filter {
  display: inline-block;
  min-height: 60px;
  padding: 8px 24px 0;
}
:host .filter .mat-form-field {
  font-size: 14px;
  width: 100%;
}
:host .table {
  height: 705px;
}
:host .mat-table {
  width: 100%;
  border-bottom: 1px solid rgb(81, 81, 81);
}
:host .mat-row {
  min-height: 40px;
  height: 43px !important;
}
:host .mat-cell {
  font-size: 13px;
}
:host .mat-header-row,
:host .mat-mdc-header-row {
  top: 0;
  position: sticky;
  z-index: 10;
  background-color: var(--mat-table-background-color);
}
:host .mat-header-cell {
  font-size: 15px;
  position: sticky;
  top: 0;
  z-index: 11;
  background-color: var(--mat-table-background-color);
}
:host .mat-column-select {
  overflow: visible;
  flex: 0 0 80px;
}
:host .mat-column-name {
  flex: 1 1 200px;
}
:host .mat-column-device {
  flex: 2 1 350px;
}
:host .mat-column-highhigh {
  flex: 0 0 140px;
}
:host .mat-column-high {
  flex: 0 0 140px;
}
:host .mat-column-low {
  flex: 0 0 140px;
}
:host .mat-column-info {
  flex: 0 0 140px;
}
:host .mat-column-actions {
  flex: 0 0 140px;
}
:host .mat-column-value {
  flex: 0 0 800px;
}
:host .mat-column-remove {
  flex: 0 0 120px;
  justify-content: flex-end;
}
:host .selectidthClass {
  flex: 0 0 50px;
}
:host .message-error {
  display: inline-block;
  color: red;
}
:host .my-header-filter ::ng-deep .mat-sort-header-button {
  display: block;
  text-align: left;
  margin-top: 5px;
}
:host .my-header-filter ::ng-deep .mat-sort-header-arrow {
  top: -12px;
  right: 20px;
}
:host .my-header-filter-input {
  display: block;
  margin-top: 4px;
  margin-bottom: 6px;
  padding: 3px 1px 3px 2px;
  border-radius: 2px;
}
:host .spinner {
  position: absolute;
  top: 50%;
  left: calc(50% - 20px);
}
:host .spinner-overlay {
  position: absolute;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
  background: rgba(0, 0, 0, 0.6);
  z-index: 99;
