  display: flex;
  align-items: center;
  justify-content: center;
  background-color: rgba(255, 255, 255, 0.08);
  color: #7ec4ff;
  flex: 0 0 38px;
}
:host .card-icon mat-icon {
  transform: scale(0.95);
}
:host .card-headline {
  flex: 1;
  min-width: 0;
}
:host .card-type {
  font-size: 11px;
  text-transform: uppercase;
  letter-spacing: 0.08em;
  color: rgba(255, 255, 255, 0.55);
  margin-bottom: 4px;
}
:host .card-name {
  font-size: 16px;
  font-weight: 600;
  line-height: 1.25;
  word-break: break-word;
}
:host .state-badge {
  width: 30px;
  height: 30px;
  border-radius: 50%;
