  align-items: center;
  justify-content: center;
  flex: 0 0 30px;
  background-color: rgba(255, 255, 255, 0.08);
}
:host .state-badge.ready {
  color: #5bca73;
  background-color: rgba(91, 202, 115, 0.14);
}
:host .state-badge.available {
  color: #f7bf53;
  background-color: rgba(247, 191, 83, 0.14);
}
:host .card-group {
  margin-top: 8px;
  margin-bottom: 8px;
  color: rgba(255, 255, 255, 0.74);
  font-size: 12px;
  min-height: 16px;
}
:host .card-versions {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 8px;
  margin-bottom: 8px;
}
