}
:host .current-box {
  border-color: rgba(63, 156, 255, 0.22);
}
:host .version-label {
  display: block;
  margin-bottom: 2px;
  font-size: 11px;
  text-transform: uppercase;
  letter-spacing: 0.06em;
  color: rgba(255, 255, 255, 0.5);
}
:host .version-value {
  display: block;
  font-size: 12px;
  font-weight: 600;
  word-break: break-word;
}
:host .card-status {
  min-height: 14px;
  margin-bottom: 8px;
  color: rgba(255, 255, 255, 0.72);
  font-size: 11px;
  word-break: break-word;
}
:host .card-actions {
  margin-top: auto;
  display: flex;
  align-items: center;
  gap: 8px;
}
:host .action-spinner {
  width: 28px;
  display: flex;
  justify-content: center;
  flex: 0 0 28px;
}
