  min-height: 240px;
  border: 1px dashed rgba(255, 255, 255, 0.12);
  border-radius: 14px;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 10px;
  color: rgba(255, 255, 255, 0.52);
}
:host .empty-state mat-icon {
  transform: scale(1.3);
}
