er;\r\n    transition: background 0.2s, color 0.2s;\r\n}\r\n.month-btn.active {\r\n    background: var(--scheduler-accent-color, #556e82);\r\n    color: var(--scheduler-secondary-text-color, #ffffff);\r\n    border-color: var(--scheduler-accent-color, #556e82);\r\n}\r\n.month-btn:hover {\r\n    background: var(--scheduler-hover-bg, #e0e0e0);\r\n    color: var(--scheduler-text-color, #333333);\r\n}\r\n.month-btn.active:hover {\r\n    background: var(--scheduler-accent-color, #556e82);\r\n    color: var(--scheduler-secondary-text-color, #ffffff);\r\n    opacity: 0.9;\r\n}\r\n\r\n// Month indicator for calendar popup (non-interactive)\r\n.month-indicator {\r\n    flex: 1;\r\n    padding: 8px 4px;\r\n    border: 1px solid #ccc;\r\n    background: #f9f9f9;\r\n    color: var(--scheduler-text-color, #333333);\r\n    border-radius: 3px;\r\n    font-size: 11px;\r\n    font-weight: 500;\r\n    margin: 2px;\r\n    display: inline-flex;\r\n    align-items: center;\r\n    justify-content: center;\r\n    min-width: 40px;\r\n    max-width: 50px;\r\n}\r\n\r\n// Active state for month indicator\r\n.month-indicator[style*=\"background: #556e82\"] {\r\n    background: var(--scheduler-accent-color, #556e82) !important;\r\n    color: var(--scheduler-secondary-text-color, #ffffff) !important;\r\n    border-color: var(--scheduler-accent-color, #556e82) !important;\r\n}\r\n\r\n// Responsive toggle row\r\n.toggle-row-responsive {\r\n  display: flex;\r\n  gap: 16px;\r\n  align-items: center;\r\n  margin-bottom: 12px;\r\n  flex-wrap: wrap;\r\n  justify-content: center;\r\n}\r\n\r\n.toggle-item {\r\n  min-width: 120px;\r\n  flex: 1 1 120px;\r\n  display: flex;\r\n  align-items: center;\r\n  justify-content: center;\r\n}\r\n.day-of-month-btn {\r\n    aspect-ratio: 1;\r\n    border-radius: 50%;\r\n    padding: 0;\r\n    margin: 0;\r\n    display: flex;\r\n    align-items: center;\r\n    justify-content: center;\r\n    font-size: 11px;\r\n    font-weight: 500;\r\n    background: #f9f9f9;\r\n    c